import * as THREE from './vendor/three.module.js';

// Textures generated by the texture-sheet skill (.claude/skills/texture-sheet).
// textures/manifest.json lists every texture with its albedo/normal files, real-world size
// (`meters`) and, for retextured facility materials, the glTF material names it replaces.
const BASE='./textures/';
const loader=new THREE.TextureLoader();
const files=new Map();
let manifest=null;

export function loadManifest(){
  manifest??=fetch(BASE+'manifest.json')
    .then(response=>response.ok?response.json():{textures:{}})
    .catch(()=>({textures:{}}));
  return manifest;
}

function loadFile(file,color){
  if(!files.has(file)){
    files.set(file,loader.loadAsync(BASE+file).then(texture=>{
      texture.wrapS=texture.wrapT=THREE.RepeatWrapping;
      texture.colorSpace=color?THREE.SRGBColorSpace:THREE.NoColorSpace;
      return texture;
    }).catch(()=>null));
  }
  return files.get(file);
}

/** Load textures by id. Missing ids or files are skipped, so the scene still builds without them. */
export async function loadTextures(ids){
  const {textures={}}=await loadManifest();
  const result=new Map();
  await Promise.all(ids.map(async id=>{
    const entry=textures[id];
    if(!entry)return;
    const [map,normalMap]=await Promise.all([
      loadFile(entry.albedo,true),
      entry.normal?loadFile(entry.normal,false):null,
    ]);
    if(map)result.set(id,{...entry,id,map,normalMap});
  }));
  return result;
}

/** Textures that replace existing facility materials, keyed by glTF material name. */
export async function loadRetexture(){
  const {textures={}}=await loadManifest();
  const ids=Object.keys(textures).filter(id=>textures[id].targets?.length);
  const loaded=await loadTextures(ids);
  const byMaterial=new Map();
  for(const texture of loaded.values())for(const name of texture.targets)byMaterial.set(name,texture);
  return byMaterial;
}

const a=new THREE.Vector3(), b=new THREE.Vector3(), c=new THREE.Vector3();
const ua=new THREE.Vector2(), ub=new THREE.Vector2(), uc=new THREE.Vector2();
function measure(mesh,stats){
  const {position,uv}=mesh.geometry.attributes;
  if(!uv)return;
  const index=mesh.geometry.index;
  const count=index?index.count:position.count;
  const at=i=>index?index.getX(i):i;
  for(let i=0;i<count;i+=3){
    a.fromBufferAttribute(position,at(i)).applyMatrix4(mesh.matrixWorld);
    b.fromBufferAttribute(position,at(i+1)).applyMatrix4(mesh.matrixWorld);
    c.fromBufferAttribute(position,at(i+2)).applyMatrix4(mesh.matrixWorld);
    stats.area+=b.sub(a).cross(c.sub(a)).length()/2;
    ua.fromBufferAttribute(uv,at(i));ub.fromBufferAttribute(uv,at(i+1));uc.fromBufferAttribute(uv,at(i+2));
    stats.uv+=Math.abs((ub.x-ua.x)*(uc.y-ua.y)-(uc.x-ua.x)*(ub.y-ua.y))/2;
  }
}

/**
 * Swap the albedo and normal maps of matching materials. The repeat is set from the mesh's own
 * UV density so each texture shows at its real-world size (`meters`).
 */
export function applyRetexture(root,byMaterial){
  if(!byMaterial?.size)return;
  root.updateMatrixWorld(true);
  const stats=new Map();
  root.traverse(object=>{
    if(!object.isMesh||Array.isArray(object.material))return;
    const material=object.material;
    if(!byMaterial.has(material.name))return;
    if(!stats.has(material))stats.set(material,{area:0,uv:0});
    measure(object,stats.get(material));
  });
  for(const [material,{area,uv}] of stats){
    const texture=byMaterial.get(material.name);
    const metersPerUv=uv>1e-9?Math.sqrt(area/uv):1;
    const repeat=Math.min(64,Math.max(.05,metersPerUv/(texture.meters||1)));
    const map=texture.map.clone();
    map.repeat.set(repeat,repeat);
    material.map=map;
    material.color.set(0xffffff);
    if(texture.normalMap){
      const normal=texture.normalMap.clone();
      normal.repeat.set(repeat,repeat);
      material.normalMap=normal;
      material.normalScale.set(1,1);
    }
    material.needsUpdate=true;
  }
}
